{ "expression" : "IF(
 AND(
 %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_DesdeAnoGananciasyPerdidas__c% >= 1900,
 %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_HastaAnoGananciasyPerdidas__c% >= 1900,
 OR(
 %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_DesdeAnoGananciasyPerdidas__c% < YEAR(TODAY()),
 AND(
 %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_DesdeAnoGananciasyPerdidas__c% == YEAR(TODAY()),
 %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_DesdeMesGananciasyPerdidas__c% <= MONTH(TODAY())
 )
 ),
 OR(
 %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_HastaAnoGananciasyPerdidas__c% < YEAR(TODAY()),
 AND(
 %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_HastaAnoGananciasyPerdidas__c% == YEAR(TODAY()),
 %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_HastaMesGananciasyPerdidas__c% <= MONTH(TODAY())
 )
 ),
 OR(
 %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_DesdeAnoGananciasyPerdidas__c% < %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_HastaAnoGananciasyPerdidas__c%,
 AND(
 %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_DesdeAnoGananciasyPerdidas__c% == %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_HastaAnoGananciasyPerdidas__c%,
 %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_DesdeMesGananciasyPerdidas__c% <= %StepEstadoGananciasPerdidas:FechaBlockGananciasyPerdidas:FSC_HastaMesGananciasyPerdidas__c%
 )
 )
 ),
 'SI',
 'NO'
)", "controlWidth" : 12, "dateFormat" : "MM-dd-yyyy", "label" : "ValidacionFechaActual", "showInputWidth" : false, "inputWidth" : 12, "hideGroupSep" : false, "hide" : true, "disOnTplt" : false, "HTMLTemplateId" : "" }

